<?php declare(strict_types=1);use FastWebsite\Core\View;$x=static fn(string$f):string=>(string)($values[$f]??'');$edit=is_int($itemId);?>
<section class="admin-page-heading"><div><p class="eyebrow">Page builder</p><h1><?=$edit?'Edit page':'Create page'?></h1><p>Save and publish the page, then add ordered content sections below.</p></div><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/pages">Back</a></section><?php if($errors!==[]):?><div class="form-alert"><ul><?php foreach($errors as$e):?><li><?=View::escape($e)?></li><?php endforeach;?></ul></div><?php endif;?><form class="content-form" method="post" action="<?=View::escape($baseUrl)?>admin/pages<?=$edit?'/'.$itemId:''?>"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><section class="form-section"><div class="form-grid"><div class="form-field span-2"><label>Title *</label><input name="title" required value="<?=View::escape($x('title'))?>"></div><div class="form-field"><label>Public URL</label><input name="slug" value="<?=View::escape($x('slug'))?>"></div><div class="form-field"><label>Parent page</label><select name="parent_page_id"><option value="">Top level</option><?php foreach($pages as$p):if((int)$p['id']===$itemId)continue;?><option value="<?=(int)$p['id']?>"<?=$x('parent_page_id')===(string)$p['id']?' selected':''?>><?=View::escape($p['title'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Template</label><select name="page_template"><option value="standard">Standard</option><option value="landing"<?=$x('page_template')==='landing'?' selected':''?>>Landing</option></select></div><div class="form-field"><label>Display order</label><input type="number" min="0" name="display_order" value="<?=View::escape($x('display_order')?:'0')?>"></div><label><input type="checkbox" name="show_in_navigation" value="1"<?=$x('show_in_navigation')==='1'?' checked':''?>> Show in navigation</label><div class="form-field span-2"><label>Search description</label><textarea name="meta_description" rows="3"><?=View::escape($x('meta_description'))?></textarea></div></div></section><div class="form-actions"><button class="button button-secondary" name="submit_action" value="save">Save</button><button class="button button-primary" name="submit_action" value="publish">Save and publish</button></div></form><?php if($edit):?><section class="admin-card" id="sections"><h2>Page sections</h2><?php if($sections===[]):?><p>No sections yet.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Order</th><th>Type</th><th>Heading</th><th></th></tr></thead><tbody><?php foreach($sections as$s):?><tr><td><?=(int)$s['display_order']?></td><td><?=View::escape($s['section_type'])?></td><td><?=View::escape($s['heading']??'Untitled section')?></td><td><form method="post" action="<?=View::escape($baseUrl)?>admin/pages/<?=$itemId?>/sections/<?=(int)$s['id']?>/remove"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button class="link-button">Remove</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><h3>Add section</h3><form class="content-form" method="post" action="<?=View::escape($baseUrl)?>admin/pages/<?=$itemId?>/sections"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><div class="form-grid"><div class="form-field"><label>Type</label><select name="section_type"><?php foreach(['rich_text','image_text','call_to_action','quote','cards','statistics','gallery','video','custom']as$t):?><option value="<?=$t?>"><?=ucwords(str_replace('_',' ',$t))?></option><?php endforeach;?></select></div><div class="form-field"><label>Order</label><input type="number" name="display_order" min="0" value="<?=count($sections)+1?>"></div><div class="form-field span-2"><label>Heading</label><input name="heading"></div><div class="form-field span-2"><label>Subheading</label><input name="subheading"></div><div class="form-field span-2"><label>Body</label><textarea name="body" rows="7"></textarea></div><div class="form-field"><label>Image</label><select name="media_id"><option value="">None</option><?php foreach($images as$i):?><option value="<?=(int)$i['id']?>"><?=View::escape($i['original_name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Button label</label><input name="button_label"></div><div class="form-field span-2"><label>Button URL</label><input name="button_url"></div><label><input type="checkbox" name="is_visible" value="1" checked> Visible</label></div><button class="button button-primary">Add section</button></form></section><?php endif;?>
